input.script:
first = boundary retry 2 {
    return list_tickets({ page: 1, status: "open" })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_tickets({ page: page, status: "open" }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
listing = fold acc = first.items for page in remaining { return acc + page }

cutoff_ms = time.parse("2026-06-03T00:00:00Z")

candidates = for t in listing {
    created_ms = time.parse(t.created_at)
    skip if created_ms >= cutoff_ms
    return t
}

escalated = for t in candidates {
    detail = boundary retry 2 { return get_ticket({ id: t.id }) } catch err {
        return fail("GET_FAILED", err.code + ": " + err.message)
    }
    body_lower = text.lower(detail.body if detail.body != null else "")
    skip if not ("refund" in body_lower)
    updated = boundary retry 2 {
        return update_ticket({ id: t.id, priority: "high", add_tags: ["billing-escalation"] })
    } catch err {
        return fail("UPDATE_FAILED", err.code + ": " + err.message)
    }
    return t.id
}

sorted_ids = list.sort(escalated)
submitted = submit_result({ answer: { escalated_ticket_ids: sorted_ids } })
return { escalated_ticket_ids: sorted_ids, submitted: submitted }
